import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.DT_qyuxR.js";const d=JSON.parse('{"title":"Conseils pour les Revenants","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/guide-joueur/03-conseils-revenants.md","filePath":"gitbook/guide-joueur/03-conseils-revenants.md"}'),n={name:"gitbook/guide-joueur/03-conseils-revenants.md"};function i(o,e,l,u,c,p){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="conseils-pour-les-revenants" tabindex="-1">Conseils pour les Revenants <a class="header-anchor" href="#conseils-pour-les-revenants" aria-label="Permalink to &quot;Conseils pour les Revenants&quot;">​</a></h1><h2 id="votre-objectif" tabindex="-1">Votre objectif <a class="header-anchor" href="#votre-objectif" aria-label="Permalink to &quot;Votre objectif&quot;">​</a></h2><p>Vous êtes Revenant (le Cercle). Vous devez <strong>éliminer tous les Vivants</strong> avant qu&#39;ils ne vous éliminent tous. Vous connaissez les autres Revenants — mais les Vivants ne vous connaissent pas.</p><h2 id="strategies-de-base" tabindex="-1">Stratégies de base <a class="header-anchor" href="#strategies-de-base" aria-label="Permalink to &quot;Stratégies de base&quot;">​</a></h2><h3 id="_1-ne-vous-faites-pas-remarquer" tabindex="-1">1. Ne vous faites pas remarquer <a class="header-anchor" href="#_1-ne-vous-faites-pas-remarquer" aria-label="Permalink to &quot;1. Ne vous faites pas remarquer&quot;">​</a></h3><p>Le meilleur Revenant est celui que personne ne soupçonne. Agissez normalement. Ne bluffez pas trop. Ne soyez pas trop calme ou trop nerveux.</p><h3 id="_2-protegez-les-allies" tabindex="-1">2. Protégez les alliés <a class="header-anchor" href="#_2-protegez-les-allies" aria-label="Permalink to &quot;2. Protégez les alliés&quot;">​</a></h3><p>Si un autre Revenant est accusé, défendez-le (subtilement). Un Revenant accusé est un Revenant en danger.</p><h3 id="_3-creez-la-confusion" tabindex="-1">3. Créez la confusion <a class="header-anchor" href="#_3-creez-la-confusion" aria-label="Permalink to &quot;3. Créez la confusion&quot;">​</a></h3><p>Accusez des Vivants entre eux. Si deux Vivants s&#39;accusent mutuellement, les Revenants peuvent frapper en silence.</p><h3 id="_4-eliminez-les-investigateurs" tabindex="-1">4. Éliminez les investigateurs <a class="header-anchor" href="#_4-eliminez-les-investigateurs" aria-label="Permalink to &quot;4. Éliminez les investigateurs&quot;">​</a></h3><p>Les masques informationnels (Medium, Oracle, Sans-Visage) sont vos ennemis prioritaires. Si le Medium examine un Revenant, le jeu est fini.</p><h3 id="_5-utilisez-les-duels-a-votre-avantage" tabindex="-1">5. Utilisez les Duels à votre avantage <a class="header-anchor" href="#_5-utilisez-les-duels-a-votre-avantage" aria-label="Permalink to &quot;5. Utilisez les Duels à votre avantage&quot;">​</a></h3><p>Un Duel est une occasion de tuer un Vivant. Mais attention : si vous perdez, votre identité est révélée.</p><h2 id="erreurs-a-eviter" tabindex="-1">Erreurs à éviter <a class="header-anchor" href="#erreurs-a-eviter" aria-label="Permalink to &quot;Erreurs à éviter&quot;">​</a></h2><h3 id="accuser-un-autre-revenant" tabindex="-1">Accuser un autre Revenant <a class="header-anchor" href="#accuser-un-autre-revenant" aria-label="Permalink to &quot;Accuser un autre Revenant&quot;">​</a></h3><p>C&#39;est l&#39;erreur fatale. Ne jamais accuser un allié.</p><h3 id="etre-trop-agressif" tabindex="-1">Être trop agressif <a class="header-anchor" href="#etre-trop-agressif" aria-label="Permalink to &quot;Être trop agressif&quot;">​</a></h3><p>Un Revenant agressif est un Revenant suspect. Calmez-vous.</p><h3 id="ignorer-les-debats" tabindex="-1">Ignorer les Débats <a class="header-anchor" href="#ignorer-les-debats" aria-label="Permalink to &quot;Ignorer les Débats&quot;">​</a></h3><p>Les Débats sont votre occasion de semer la confusion. Ne les négligez pas.</p><h3 id="reveler-votre-camp" tabindex="-1">Révéler votre camp <a class="header-anchor" href="#reveler-votre-camp" aria-label="Permalink to &quot;Révéler votre camp&quot;">​</a></h3><p>Ne dites jamais que vous êtes Revenant. Évidemment.</p><h2 id="strategies-avancees" tabindex="-1">Stratégies avancées <a class="header-anchor" href="#strategies-avancees" aria-label="Permalink to &quot;Stratégies avancées&quot;">​</a></h2><h3 id="le-parfait-innocent" tabindex="-1">Le parfait innocent <a class="header-anchor" href="#le-parfait-innocent" aria-label="Permalink to &quot;Le parfait innocent&quot;">​</a></h3><p>Jouez comme un Vivant parfait. Accusez d&#39;autres joueurs (des Revenants, en privé). Créez l&#39;illusion que vous êtes du bon côté.</p><h3 id="le-bouc-emissaire" tabindex="-1">Le bouc émissaire <a class="header-anchor" href="#le-bouc-emissaire" aria-label="Permalink to &quot;Le bouc émissaire&quot;">​</a></h3><p>Si un Revenant est acculé, sacrifiez-le. Laissez-le mourir en laissant une rumeur fausse. Les Vivants vont croire ses derniers mots.</p><h3 id="le-piege-vocal" tabindex="-1">Le piège vocal <a class="header-anchor" href="#le-piege-vocal" aria-label="Permalink to &quot;Le piège vocal&quot;">​</a></h3><p>Utilisez les zones vocales à votre avantage. Si un Vivant est isolé, c&#39;est une cible facile pour le Poursuite ou le Sacrifice.</p><h2 id="conseils-par-masque" tabindex="-1">Conseils par masque <a class="header-anchor" href="#conseils-par-masque" aria-label="Permalink to &quot;Conseils par masque&quot;">​</a></h2><h3 id="si-vous-portez-un-masque-informationnel" tabindex="-1">Si vous portez un masque informationnel <a class="header-anchor" href="#si-vous-portez-un-masque-informationnel" aria-label="Permalink to &quot;Si vous portez un masque informationnel&quot;">​</a></h3><p>Vous êtes dans une position paradoxale : vos pouvoirs révèlent des informations, mais vous êtes Revenant. Utilisez-les pour orienter les investigations vers des Vivants.</p><h3 id="si-vous-portez-un-masque-offensif" tabindex="-1">Si vous portez un masque offensif <a class="header-anchor" href="#si-vous-portez-un-masque-offensif" aria-label="Permalink to &quot;Si vous portez un masque offensif&quot;">​</a></h3><p>Vous êtes l&#39;assassin du Cercle. Frappez pendant la nuit. Utilisez vos dégâts pour éliminer les Vivants sans vous faire remarquer.</p><h3 id="si-vous-portez-un-masque-de-support" tabindex="-1">Si vous portez un masque de support <a class="header-anchor" href="#si-vous-portez-un-masque-de-support" aria-label="Permalink to &quot;Si vous portez un masque de support&quot;">​</a></h3><p>Vous êtes le protecteur du Cercle. Soignez vos alliés Revenants. Maintenez-les en vie.</p>',37)])])}const h=a(n,[["render",i]]);export{d as __pageData,h as default};
